hl.on("hyprland.start", function()
    hl.exec_cmd("env QT_MEDIA_BACKEND=ffmpeg qs")
    hl.exec_cmd("pkill dunst")
    hl.exec_cmd("pkill mako")
    hl.exec_cmd("pkill swaync")
    hl.exec_cmd("awww-daemon")
    -- lockscreen at login disabled (SDDM already asks for the password); SUPER+L still locks
    hl.exec_cmd("udiskie")
    hl.exec_cmd("/usr/bin/waybar")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("~/.config/quickshell/wave-check.sh")
end)

